def build():
    doc = Document()

    # Style: section heading
    styles = doc.styles
    # Title page block
    title = doc.add_paragraph()
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = title.add_run('Тезисы (флэш-карты) докладчика к защите диссертации')
    run.bold = True; run.font.size = Pt(16)

    sub = doc.add_paragraph()
    sub.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = sub.add_run('по теме «Разработка состязательно устойчивых моделей '
                      'на основе искусственного интеллекта в гибридных системах '
                      'обнаружения и предотвращения вторжений для сетевой '
                      'безопасности»')
    run.italic = True; run.font.size = Pt(12)

    auth = doc.add_paragraph()
    auth.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = auth.add_run('Аспирант: Анаедевха Роджер Ник (А23–501)\n'
                       'Научный руководитель: к.т.н., доцент Трофимов А. Г.\n'
                       'НИЯУ МИФИ, кафедра кибернетики № 22\n'
                       'Москва, 2026 г.')
    run.font.size = Pt(11)

    # Usage instruction
    doc.add_paragraph()
    inst = doc.add_paragraph()
    run = inst.add_run('Назначение документа. ')
    run.bold = True; run.font.size = Pt(11)
    inst.add_run('Настоящие тезисы предназначены для самостоятельного '
                 'чтения членами диссертационного совета во время устной '
                 'презентации. По каждому слайду — 2–3 кратких предложения '
                 'на простом языке, без специальной терминологии.')

    doc.add_page_break()

    # Notes per slide
    for num, slide_title, note in NOTES:
        p1 = doc.add_paragraph()
        h = p1.add_run(f'Слайд {num}. {slide_title}')
        h.bold = True; h.font.size = Pt(12)
        h.font.color.rgb = RGBColor(0x14, 0x28, 0x5A)  # navy

        p2 = doc.add_paragraph()
        p2.paragraph_format.left_indent = Cm(0.5)
        p2.paragraph_format.space_after = Pt(10)
        body = p2.add_run(note)
        body.font.size = Pt(11)

    # Final reminder
    doc.add_page_break()
    p = doc.add_paragraph()
    h = p.add_run('Напоминание докладчику.')
    h.bold = True; h.font.size = Pt(12)
    p = doc.add_paragraph()
    p.add_run('После заключительного слайда сделать паузу '
              'для вопросов диссертационного совета. На каждый '
              'вопрос отвечать спокойно, конкретно и со ссылкой '
              'на соответствующий слайд или раздел диссертации. '
              'Время основного доклада — 18–20 минут; время на '
              'вопросы — до 40 минут.').font.size = Pt(11)

    out = '/home/user/CV/submission_docs/filled/05_Speaker_Notes_Anaedevha.docx'
    doc.save(out)
    print('wrote:', out)


if __name__ == '__main__':
    build()
